const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString('en-AU');
let token='',page='overview',index=1,search='',options,request=0,sortKey='',sortDirection='asc';
const names={overview:['Supply chain overview','From component lots to the customers they reach.'],products:['Product catalogue','Explore models, configurations and the stock available to fulfil them.'],stock:['Inventory','Review warehouse balances and manage manufacturing quality holds.'],orders:['Orders & dispatch','Follow retailer demand from submission to fulfilment.'],trace:['Component tracing','Find every manufacturing batch, stock position and recipient linked to a component lot.']};
const badge=s=>`<span class="badge ${esc(s)}">${esc(String(s).replaceAll('_',' '))}</span>`;
function notice(text,error=false){$('#notice').hidden=false;$('#notice').className=error?'error':'';$('#notice').textContent=text;}
async function api(path,data){const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json','X-Tracey-Token':token},body:JSON.stringify(data)}:{});const result=await r.json();if(!r.ok)throw Error(result.error+(result.rolled_back?' No changes were saved.':''));return result;}
function table(head,rows,sortable=false){return rows.length?`<div class="table-wrap"><table><thead><tr>${head.map(h=>sortable?sortHeading(h):`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching records found.</div>';}

const sortColumns={products:{Product:[['Product','product']],'Chip / storage':[['Chip','chip'],['Storage','storage']],Colour:[['Colour','colour']],SKU:[['SKU','sku']],Available:[['Available','available']]},stock:{'Product / batch':[['Product','product'],['Batch','batch']],Warehouse:[['Warehouse','warehouse']],'On hand':[['On hand','on_hand']],Reserved:[['Reserved','reserved']],Eligible:[['Eligible','eligible']],Quality:[['Quality','quality']]},orders:{Order:[['Order','order']],Retailer:[['Retailer','retailer']],Created:[['Created','created']],Units:[['Units','units']],Status:[['Status','status']]}};
function sortHeading(label){const fields=sortColumns[page][label];if(!fields)return '<th scope="col">'+label+'</th>';const selected=fields.some(([,key])=>key===sortKey);return `<th scope="col"${selected?' aria-sort="'+(sortDirection==='asc'?'ascending':'descending')+'"':''}>${fields.map(([text,key])=>`<button type="button" class="sort-button" data-sort="${key}" aria-label="Sort by ${text.toLowerCase()} ${sortKey===key&&sortDirection==='asc'?'descending':'ascending'}">${text}<span aria-hidden="true">${sortKey===key?(sortDirection==='asc'?'↑':'↓'):'↕'}</span></button>`).join('<span class="sort-divider"> / </span>')}</th>`;}

function toolbar(hint){return `<div class="toolbar"><form id="search-form"><input aria-label="Search records" id="search" placeholder="${hint}" value="${esc(search)}"><button>Search</button></form><button id="refresh">↻ Refresh</button></div>`;}
function pager(more){return `<div class="pager"><button id="prev" ${index===1?'disabled':''}>← Previous</button><span>Page ${index}</span><button id="next" ${more?'':'disabled'}>Next →</button></div>`;}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog-error').hidden=true;if(!$('#dialog').open)$('#dialog').showModal();}
function errorDialog(e){$('#dialog-error').hidden=false;$('#dialog-error').textContent=e.message;}
async function action(button,fn){button.disabled=true;try{await fn();}catch(e){if($('#dialog').open)errorDialog(e);else notice(e.message,true);}finally{button.disabled=false;}}
async function load(){const ticket=++request;$('#content').classList.add('loading');try{
 if(page==='overview'){const d=await api('/api/summary');if(ticket!==request)return;$('#connection').textContent=d.database+' · Connected';$('#content').innerHTML=`<div class="cards">${[['Available stock',d.available,'Released and unreserved units'],['Retailer orders',d.orders,'Across the distribution network'],['Product configurations',d.configurations,d.models+' shared models'],['Component types',d.components,'Parts, assemblies and complete sets']].map(([t,n,h])=>`<div class="card"><div class="label">${t}</div><strong>${fmt(n)}</strong><small>${h}</small></div>`).join('')}</div><div class="grid"><div class="panel"><div class="panel-head"><div><h2>One connected supply chain</h2><p>Move from demand to delivery, with traceability at every step.</p></div></div><div class="steps"><div><span class="step-num">01</span><h3>Check availability</h3><p>Find eligible stock across warehouses. Held batches stay out of allocation.</p><button data-go="stock">Explore inventory →</button></div><div><span class="step-num">02</span><h3>Fulfil demand</h3><p>Create a retailer order, reserve its stock and dispatch a shipment.</p><button data-create>Create an order →</button></div><div><span class="step-num">03</span><h3>Trace the source</h3><p>Follow a component lot to finished batches and affected recipients.</p><button data-go="trace">Trace components →</button></div></div></div><div class="panel"><h2>Order pipeline</h2><p class="help">Current status of retailer orders</p>${d.status.map(s=>`<div class="status-row"><div><span>${esc(s.order_status.replaceAll('_',' '))}</span><strong>${fmt(s.count)}</strong></div><progress class="bar" aria-label="${esc(s.order_status)} orders" value="${Number(s.count)}" max="${Math.max(1,Number(d.orders))}"></progress></div>`).join('')}</div></div><div class="callout"><div><h3>Quality and traceability</h3><p>${fmt(d.held)} manufacturing batch on hold. Start with component lot 11 to explore the seeded recall scenario.</p></div><button data-go="trace">Open tracing →</button></div>`;
 }else if(['products','stock','orders'].includes(page)){const rows=await api(`/api/${page}?q=${encodeURIComponent(search)}&page=${index}&sort=${encodeURIComponent(sortKey)}&direction=${sortDirection}`);if(ticket!==request)return;const more=rows.length>30;rows.splice(30);let html='';if(page==='products')html=table(['Product','Chip / storage','Colour','SKU','Available'],rows.map(r=>[`<strong>${esc(r.model_name)}</strong><small>${esc(r.product_family)} · ${esc(r.release_year||'Year unspecified')}</small>`,esc(r.chip||'—')+'<small>'+esc(r.storage_capacity_gb?fmt(r.storage_capacity_gb)+' GB':'—')+'</small>',esc(r.colour||'—'),esc(r.sku),`<strong>${fmt(r.available)}</strong>`]),true);if(page==='stock')html=table(['Product / batch','Warehouse','On hand','Reserved','Eligible','Quality',''],rows.map(r=>[`<strong>${esc(r.model_name)}</strong><small>Batch ${r.manufacturing_batch_id} · ${esc(r.sku)}</small>`,esc(r.city),fmt(r.on_hand_qty),fmt(r.reserved_qty),`<strong>${fmt(r.eligible)}</strong>`,badge(r.quality_status),r.quality_status==='released'?`<button class="mini danger" data-hold="${r.manufacturing_batch_id}">Place on hold</button>`:'—']),true);if(page==='orders')html=table(['Order','Retailer','Created','Units','Status',''],rows.map(r=>[`<strong>#${r.order_id}</strong>`,esc(r.retailer_name),esc(new Date(r.ordered_at).toLocaleDateString('en-AU')),fmt(r.units),badge(r.order_status),`<button class="link" data-order="${r.order_id}">View order →</button>`]),true);$('#content').innerHTML=toolbar(page==='stock'?'Search product, city or batch…':page==='orders'?'Search order, retailer or status…':'Search model, chip, colour or SKU…')+html+pager(more);
 }else{$('#content').innerHTML=`<div class="panel"><h2>Start with a component lot</h2><p>Enter a received component lot ID to trace its downstream impact.</p><form id="trace-form" class="toolbar"><label class="field"><span>Component lot ID</span><input id="lot-id" type="number" min="1" value="11" required></label><button class="primary">Trace lot →</button></form></div><div id="trace-result"></div>`;}
 }catch(e){notice(e.message,true);$('#connection').textContent='Connection needs attention';$('#content').innerHTML='<div class="empty">Unable to load this view. <button id="refresh">Try again</button></div>';}finally{if(ticket===request)$('#content').classList.remove('loading');}}
function navigate(target){page=target;index=1;search='';sortKey='';sortDirection='asc';$('#notice').hidden=true;$('#title').textContent=names[page][0];$('#subtitle').textContent=names[page][1];$('#crumb').textContent=page==='overview'?'Overview':names[page][0];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});load();}
async function newOrder(){modal('Create retailer order','<div class="empty">Loading products and retailers…</div>');try{options=options||await api('/api/options');$('#dialog-body').innerHTML=`<form id="order-form"><label class="field"><span>Retailer</span><select name="retailer" required>${options.retailers.map(r=>`<option value="${r.retailer_id}">${esc(r.retailer_name)}</option>`).join('')}</select></label><label class="field"><span>Product configurations and quantities</span></label><div id="lines"></div><button type="button" id="add-line">＋ Add product</button><label class="check"><input name="allocate" type="checkbox" checked>Create and allocate in one transaction</label><p class="help">If any line has insufficient eligible stock, neither the order nor its reservations will be saved. Untick to save a submitted order without allocating stock.</p><div class="actions"><button type="submit" class="primary">Save order</button></div></form>`;addLine();}catch(e){errorDialog(e);}}
function addLine(){if($('#lines').children.length>=20)return;const div=document.createElement('div');div.className='line';div.innerHTML=`<select aria-label="Product configuration" required><option value="">Choose a product…</option>${options.products.map(p=>`<option value="${esc(p.sku)}">${esc(p.display_name)} · ${esc(p.sku)}</option>`).join('')}</select><input aria-label="Quantity" type="number" min="1" max="2147483647" step="1" value="1" required><button type="button" class="icon remove-line" aria-label="Remove product">×</button>`;$('#lines').append(div);}
async function viewOrder(id){const d=await api('/api/order?id='+id);modal('Order #'+id,`<div class="panel-head"><div><h3>${esc(d.order.retailer_name)}</h3><p>${esc(new Date(d.order.ordered_at).toLocaleString('en-AU'))}</p></div>${badge(d.order.order_status)}</div>${table(['Line','Product','Ordered'],d.lines.map(l=>[l.line_number,esc(l.display_name),fmt(l.ordered_qty)]))}${d.order.order_status==='submitted'?`<div class="actions"><button class="primary" data-allocate="${id}">Allocate stock</button></div>`:''}<h3 class="section-label">Stock allocations</h3>${table(['Allocation / batch','Warehouse','Allocated','To ship','Dispatch'],d.allocations.map(a=>[`#${a.allocation_id}<small>Batch ${a.manufacturing_batch_id} · ${esc(a.quality_status)}</small>`,esc(a.city),fmt(a.allocated_qty),fmt(a.remaining),a.remaining>0&&a.quality_status==='released'?`<form class="dispatch-form" data-id="${a.allocation_id}" data-order="${id}"><input aria-label="Dispatch quantity" type="number" min="1" max="${a.remaining}" value="${a.remaining}" required><button class="mini">Dispatch</button></form>`:'—']))}<h3 class="section-label">Shipments</h3>${table(['Shipment','Dispatched','Units','Destination'],d.shipments.map(s=>['#'+s.shipment_id,esc(new Date(s.dispatched_at).toLocaleString('en-AU')),fmt(s.shipped_qty),esc(s.delivery_address)]))}`);}
async function trace(id){const d=await api('/api/trace?id='+id);$('#trace-result').innerHTML=`<div class="lot-summary"><span class="badge">COMPONENT LOT ${d.lot.component_batch_id}</span><h2>${esc(d.lot.component_name)}</h2><p>${esc(d.lot.supplier_name)} · ${esc(d.lot.supplier_lot_code)} · Received ${esc(d.lot.received_date)}</p></div><div class="trace-grid">${[['Affected manufacturing batches',d.batches.length],['Remaining units in stock',d.stock.reduce((n,r)=>n+r.on_hand_qty,0)],['Potentially affected shipped units',d.recipients.reduce((n,r)=>n+Number(r.shipped_qty),0)]].map(([label,n])=>`<div class="card"><div class="label">${label}</div><strong>${fmt(n)}</strong></div>`).join('')}</div><h3 class="section-label">1. Manufacturing batches</h3>${table(['Batch','Product','Input used','Produced','Quality',''],d.batches.map(b=>['#'+b.manufacturing_batch_id,esc(b.model_name),fmt(b.quantity_used),fmt(b.produced_qty),badge(b.quality_status),b.quality_status==='released'?`<button class="mini danger" data-hold="${b.manufacturing_batch_id}" data-lot="${id}">Place on hold</button>`:'—']))}<h3 class="section-label">2. Remaining warehouse stock</h3>${table(['Batch','Warehouse','On hand','Reserved','Quality'],d.stock.map(s=>['#'+s.manufacturing_batch_id,esc(s.city),fmt(s.on_hand_qty),fmt(s.reserved_qty),badge(s.quality_status)]))}<h3 class="section-label">3. Recipients already supplied</h3>${table(['Shipment / order','Retailer','Batch','Units','Recorded destination'],d.recipients.map(r=>['#'+r.shipment_id+' / #'+r.order_id,esc(r.retailer_name),'#'+r.manufacturing_batch_id,fmt(r.shipped_qty),esc(r.delivery_address)]))}`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.sort){sortDirection=sortKey===b.dataset.sort&&sortDirection==='asc'?'desc':'asc';sortKey=b.dataset.sort;index=1;load();return;}if(b.dataset.page)navigate(b.dataset.page);if(b.dataset.go)navigate(b.dataset.go);if(b.id==='new-order'||b.hasAttribute('data-create'))newOrder();if(b.id==='close-dialog')$('#dialog').close();if(b.id==='refresh'){sortKey='';sortDirection='asc';index=1;load();}if(b.id==='next'){index++;load();}if(b.id==='prev'){index--;load();}if(b.id==='add-line')addLine();if(b.classList.contains('remove-line')&&$('#lines').children.length>1)b.closest('.line').remove();if(b.dataset.order)action(b,()=>viewOrder(b.dataset.order));if(b.dataset.allocate)action(b,async()=>{await api('/api/allocate',{id:Number(b.dataset.allocate)});await viewOrder(b.dataset.allocate);load();notice('Stock allocated successfully.');});if(b.dataset.hold){const id=Number(b.dataset.hold),lot=b.dataset.lot;modal('Place batch #'+id+' on hold',`<p>This will block new allocations and dispatches from this manufacturing batch. Existing reservations remain recorded.</p><p class="help">This prototype does not provide a release-from-hold workflow.</p><div class="actions"><button id="cancel-hold">Cancel</button><button id="confirm-hold" class="danger">Place batch on hold</button></div>`);$('#cancel-hold').onclick=()=>$('#dialog').close();$('#confirm-hold').onclick=ev=>action(ev.target,async()=>{await api('/api/hold',{id});$('#dialog').close();notice('Batch #'+id+' is now held.');if(lot)await trace(lot);else await load();});}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type="submit"]')||f.querySelector('button');if(f.id==='search-form'){search=$('#search').value;index=1;load();}if(f.id==='trace-form')action(b,()=>trace($('#lot-id').value));if(f.id==='order-form')action(b,async()=>{const lines=[...$('#lines').children].map(l=>({sku:l.querySelector('select').value,qty:Number(l.querySelector('input').value)}));const result=await api('/api/orders',{retailer_id:Number(f.elements.retailer.value),allocate:f.elements.allocate.checked,lines});navigate('orders');await viewOrder(result.order_id);notice('Order #'+result.order_id+' saved.');});if(f.classList.contains('dispatch-form'))action(b,async()=>{const r=await api('/api/dispatch',{id:Number(f.dataset.id),qty:Number(f.querySelector('input').value)});await viewOrder(f.dataset.order);load();notice('Shipment #'+r.shipment_id+' dispatched.');});});
api('/api/session').then(s=>{token=s.token;navigate('overview');}).catch(e=>notice(e.message,true));

document.querySelector('.brand').addEventListener('click',()=>navigate('overview'));
